import { test, expect } from '@playwright/test';

test.describe('Search Bar Expansion on Focus', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://yourwebsite.com');
    await page.setViewportSize({ width: 375, height: 812 }); // Mobile viewport
  });

  test('should expand search bar on focus', async ({ page }) => {
    const searchBar = page.getByRole('textbox', { name: /search/i });
    await searchBar.focus();
    const expandedSearchBar = page.getByRole('textbox', { name: /search/i }).evaluate(el => el.style.width);
    expect(expandedSearchBar).toBe('100%'); // Assuming the expanded width is 100%
  });

  test('should collapse search bar on blur', async ({ page }) => {
    const searchBar = page.getByRole('textbox', { name: /search/i });
    await searchBar.focus();
    await searchBar.blur();
    const collapsedSearchBar = page.getByRole('textbox', { name: /search/i }).evaluate(el => el.style.width);
    expect(collapsedSearchBar).toBe('50px'); // Assuming the collapsed width is 50px
  });
});
